'use strict';
(() => {
  const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function render(data, lang='zh') {
    const tr=(zh,en)=>lang==='en'?en:zh;
    if(!data)return `<div class="empty">${tr('老板看板暂未加载，请刷新重试。','The executive overview is unavailable. Refresh to retry.')}</div>`;
    const pct=value=>value===null?'—':`${value}%`;
    const metric=(label,value,note)=>`<div class="stat-card"><div class="stat-label">${label}</div><div class="stat-value num">${esc(value)}</div><div class="stat-note">${note}</div></div>`;
    const progress=value=>value===null?`<span class="fine">${tr('暂无指标','No metrics')}</span>`:`<div class="exec-progress"><strong>${pct(value)}</strong><div class="progress"><span style="width:${Math.max(0,Math.min(100,value))}%"></span></div></div>`;
    const labels={todo:tr('待开始','Not started'),planned:tr('已分派','Assigned'),doing:tr('进行中','In progress'),blocked:tr('有阻塞','Blocked'),review:tr('待验收','Awaiting review'),submitted:tr('待验收','Awaiting review'),revision:tr('待补充','Needs more evidence')};
    const time=new Intl.DateTimeFormat(lang==='en'?'en-GB':'zh-CN',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Shanghai'}).format(new Date(data.generatedAt));
    return `<div class="page-heading"><div><div class="eyebrow">COMPANY AT A GLANCE</div><h1>${tr('老板看板','Executive overview')}</h1><p>${tr('目标到哪里了，交付怎么样，哪些事项需要你协调。','See goal progress, delivery outcomes and where your help is needed.')}</p></div><div class="exec-asof"><span class="badge">${data.demo?tr('虚构数据演示','Fictional demo'):tr('全公司 · 只读','Company-wide · read-only')}</span><p class="fine">${tr('数据快照','Snapshot')} · ${esc(time)} (UTC+8)</p></div></div>
    <div class="stats-grid">${metric(tr('公司 OKR 进度','Company OKR progress'),pct(data.companyProgress),tr('公司目标等权；目标内有效 KR 等权','Equal weight per company objective and valid KR'))}${metric(tr('已验收 / 全部任务','Accepted / all tasks'),`${data.totals.accepted} / ${data.totals.total}`,tr('人工验收后的交付记录','Deliveries confirmed by human review'))}${metric(tr('等待成果验收','Awaiting review'),data.totals.waiting,tr('提交成果后，等待指定负责人验收','Submitted and awaiting the designated reviewer'))}${metric(tr('逾期未验收','Overdue & unaccepted'),data.totals.overdue,tr('按当前截止时间计算，可与待验收重叠','Based on current due dates; may include pending reviews'))}</div>
    <div class="exec-note">${tr('统计范围：系统内全部已记录任务；不代表尚未导入的工作。业务 KR 与任务数量分别计算。','Scope: all tasks recorded in this system; work not yet imported is excluded. Business KRs are separate from task counts.')}</div>
    <section class="panel exec-panel"><div class="panel-head"><div><h2>${tr('部门全景','Department overview')}</h2><p>${tr('看交付和协作压力，不按任务数量给部门排名。','Compare delivery and coordination needs, without ranking departments by task count.')}</p></div></div><div class="table-wrap"><table class="task-table exec-table"><thead><tr>${[tr('部门','Department'),tr('已录入在职人数','Active recorded members'),tr('全部任务','All tasks'),tr('已验收','Accepted'),tr('待验收','Awaiting review'),tr('逾期','Overdue'),tr('部门 OKR','Department OKRs')].map(s=>`<th>${s}</th>`).join('')}</tr></thead><tbody>${data.departments.map(d=>{const gs=data.goals.filter(g=>g.departmentId===d.id&&g.progress!==null);const p=gs.length?Math.round(gs.reduce((s,g)=>s+g.progress,0)/gs.length):null;return `<tr><td><strong>${esc(d.name)}</strong></td><td>${d.members}</td><td>${d.total}</td><td>${d.accepted}</td><td>${d.waiting}</td><td>${d.overdue}</td><td>${progress(p)}</td></tr>`;}).join('')||`<tr><td colspan="7">${tr('尚未同步部门','No departments synchronized yet')}</td></tr>`}</tbody></table></div></section>
    <div class="dashboard-grid exec-lower"><section class="panel"><div class="panel-head"><div><h2>${tr('需要协调与跟进','Needs coordination & follow-up')}</h2><p>${data.demo?tr('逾期、阻塞、待验收、待补充；优先显示最早截止事项。','Overdue, blocked, awaiting review or revision; earliest deadlines first.'):tr('逾期、待验收、待补充；优先显示最早截止事项。','Overdue, awaiting review or revision; earliest deadlines first.')}</p></div></div>${data.risks.map(r=>`<article class="exec-risk"><div><h3>${esc(r.title)}</h3><p class="fine">${esc(r.owner)} · ${esc(r.department)} · ${esc(String(r.due).slice(0,10))}</p></div><div class="exec-risk-labels"><span class="badge ${r.status==='blocked'?'red':'amber'}">${esc(labels[r.status]||r.status)}</span>${r.overdue?`<span class="badge red">${tr('逾期','Overdue')}</span>`:''}</div></article>`).join('')||`<div class="empty">${tr('当前没有需要跟进的记录','No follow-up items recorded')}</div>`}<div class="panel-body fine">${tr('最多显示','Showing up to')} ${data.riskLimit} ${tr('项；完整数量见上方统计。','items; full counts are shown above.')}</div></section><section class="panel"><div class="panel-head"><h2>${tr('公司目标','Company objectives')}</h2></div>${data.goals.filter(g=>g.level==='company').map(g=>`<article class="mini-objective"><h3>${esc(g.title)}</h3>${progress(g.progress)}</article>`).join('')||`<div class="empty">${tr('尚未录入公司目标','No company objectives recorded')}</div>`}<div class="panel-body"><p class="fine">${tr('缺少 KR 时显示“—”，不把缺失数据当成零分。','Missing KRs display “—”; missing data is not a zero score.')}</p><p class="fine">${tr('薪资成本与历史趋势尚无核验数据，暂不展示估算值。','Salary costs and historical trends are omitted until verified data is available.')}</p></div></section></div>`;
  }
  window.WorkOSExecutive={render};
})();
